import SwiftUI

// Real lateral-brain vector art, embedded from a CC0 side-view brain drawing
// (freesvg.org, "human brain / a brain from the side", public domain). The two
// original SVG paths were normalized to absolute M/L/C/Z in viewBox 6599x4284:
//   `body`  = the silhouette fill; `lines` = the outline + gyri detail.
// Parsed once into SwiftUI Paths; MiniBrainView fits + tints them and glows the
// frontal regions the content engages.
enum BrainArt {
    static let viewBox = CGSize(width: 6599, height: 4284)
    static let body: Path = parse(bodyD)
    static let lines: Path = parse(linesD)

    private static func parse(_ d: String) -> Path {
        var path = Path()
        let toks = d.split(separator: " ")
        var i = 0
        func n() -> CGFloat { defer { i += 1 }; return CGFloat(Double(toks[i]) ?? 0) }
        while i < toks.count {
            let t = toks[i]; i += 1
            switch t {
            case "M": path.move(to: CGPoint(x: n(), y: n()))
            case "L": path.addLine(to: CGPoint(x: n(), y: n()))
            case "C":
                let c1 = CGPoint(x: n(), y: n())
                let c2 = CGPoint(x: n(), y: n())
                let e  = CGPoint(x: n(), y: n())
                path.addCurve(to: e, control1: c1, control2: c2)
            case "Z": path.closeSubpath()
            default: break
            }
        }
        return path
    }

